  -f, --file file                    Template file to process. Omit to use standard input, or use --in or --input-dir (default [-])
  -i, --in string                    Template string to process (alternative to --file and --input-dir)
      --input-dir directory          directory which is examined recursively for templates (alternative to --file and --in)
      --exclude strings              glob of files to not parse
      --exclude-processing strings   glob of files to be copied without parsing
      --include strings              glob of files to parse
  -o, --out file                     output file name. Omit to use standard output. (default [-])
  -t, --template strings             Additional template file(s)
      --output-dir directory         directory to store the processed templates. Only used for --input-dir (default ".")
      --output-map string            Template string to map the input file to an output path
      --chmod string                 set the mode for output file(s). Omit to inherit from input file(s)
      --exec-pipe                    pipe the output to the post-run exec command
      --left-delim delimiter         override the default left-delimiter [$GOMPLATE_LEFT_DELIM] (default "{{")
      --right-delim delimiter        override the default right-delimiter [$GOMPLATE_RIGHT_DELIM] (default "}}")
      --missing-key string           Control the behavior during execution if a map is indexed with a key that is not present in the map. error (default) - return an error, zero - fallback to zero value, default/invalid - print <no value> (default "error")
      --experimental                 enable experimental features [$GOMPLATE_EXPERIMENTAL]
  -V, --verbose                      output extra information about what gomplate is doing
      --config string                config file (overridden by commandline flags) (default ".gomplate.yaml")
  -h, --help                         help for gomplate
  -v, --version                      version for gomplate
`

type Config struct {
    Datasources []string
    Headers []string
    Contexts []string
    Plugins []string
    InputFiles []string
    In *string
    InputDir string
    OutputFiles []string
    Templates []string
    OutputDir string
    OutputMap string
    Excludes []string
    ExcludeProcessing []string
    Includes []string
    Chmod string
    ExecPipe bool
    LeftDelim string
    RightDelim string
    MissingKey string
    Verbose bool
    Experimental bool
    ConfigPath string
    ConfigDisabled bool
    cliSet map[string]bool
}

type App struct {
    cfg Config
    dsURLs map[string]string
    dsHeaders map[string]map[string][]string
    dsCache map[string]interface{}
    dsRaw map[string]string
    stdinOnce bool
    stdinData []byte
    tmpl *template.Template
    currentPath string
    plugins map[string]string
}

type logEntry struct {
    Time string `json:"time"`
    Level string `json:"level"`
    Msg string `json:"msg"`
    Err string `json:"err"`
}

func main() { os.Exit(run()) }

func run() int {
    cfg := defaultConfig()
    parsed, code, err := parseArgs(os.Args[1:], &cfg)
    if !parsed {
        if err != nil {
            fmt.Print(helpText)
            fmt.Fprintf(os.Stderr, "Error: %s\n", err)
            fmt.Fprintf(os.Stderr, "ERROR  err=%q\n", err.Error())
            return code
        }
        return code
    }
    if code != -1 { return code }

    // Apply config file after CLI parsing, but only for flags not set on CLI.
    if !cfg.ConfigDisabled && cfg.ConfigPath != "" {
        if _, statErr := os.Stat(cfg.ConfigPath); statErr == nil {
            if err := applyConfigFile(&cfg, cfg.ConfigPath); err != nil {
                fmt.Print(helpText)
                fmt.Fprintf(os.Stderr, "Error: %s\n", err)
                logError(err.Error())
                return 1
            }
        }
    }
    app := &App{cfg: cfg, dsURLs: map[string]string{}, dsHeaders: map[string]map[string][]string{}, dsCache: map[string]interface{}{}, dsRaw: map[string]string{}, plugins: map[string]string{}}
    app.loadDefs()
    if err := app.validate(); err != nil { logError(err.Error()); return 1 }
    if err := app.execute(); err != nil { logError(err.Error()); return 1 }
    return 0
}

func defaultConfig() Config {
    l := os.Getenv("GOMPLATE_LEFT_DELIM"); if l=="" { l="{{" }
    r := os.Getenv("GOMPLATE_RIGHT_DELIM"); if r=="" { r="}}" }
    cp := os.Getenv("GOMPLATE_CONFIG"); if cp=="" { cp = ".gomplate.yaml" }
    return Config{LeftDelim:l, RightDelim:r, MissingKey:"error", OutputDir:".", ConfigPath:cp, cliSet:map[string]bool{}}
}

func parseArgs(args []string, cfg *Config) (bool,int,error) {
    for i:=0; i<len(args); i++ {
        a:=args[i]
        if a=="" { continue }
        if !strings.HasPrefix(a,"-") || a=="-" { return false,1,fmt.Errorf("unknown command %q for \"gomplate\"", a) }
        name,val,hasVal:=a,"",false
        if strings.HasPrefix(a,"--") {
            if idx:=strings.Index(a,"="); idx>=0 { name=a[:idx]; val=a[idx+1:]; hasVal=true }
        } else if strings.HasPrefix(a,"-") && len(a)>2 {
            if a[2]=='=' { name=a[:2]; val=a[3:]; hasVal=true } else { name=a[:2]; if len(a)>2 { val=a[2:]; hasVal=true } }
        }
        need := func() (string,error) { if hasVal { return val,nil }; if i+1>=len(args) { return "",fmt.Errorf("flag needs an argument: %s", name) }; i++; return args[i],nil }
        set := func(k string){ cfg.cliSet[k]=true }
        switch name {
        case "-h","--help": fmt.Print(helpText); return true,0,nil
        case "-v","--version": fmt.Println("gomplate version 0.0.0"); return true,0,nil
        case "-V","--verbose": cfg.Verbose=true; set("verbose")
        case "--experimental": cfg.Experimental=true; set("experimental")
        case "--exec-pipe": cfg.ExecPipe=true; set("execPipe")
        case "-d","--datasource": v,e:=need(); if e!=nil{return false,1,e}; cfg.Datasources=append(cfg.Datasources,v); set("datasources")
        case "-H","--datasource-header": v,e:=need(); if e!=nil{return false,1,e}; cfg.Headers=append(cfg.Headers,v); set("headers")
        case "-c","--context": v,e:=need(); if e!=nil{return false,1,e}; cfg.Contexts=append(cfg.Contexts,v); set("context")
        case "--plugin": v,e:=need(); if e!=nil{return false,1,e}; cfg.Plugins=append(cfg.Plugins,v); set("plugins")
        case "-f","--file": v,e:=need(); if e!=nil{return false,1,e}; cfg.InputFiles=append(cfg.InputFiles,v); set("inputFiles")
        case "-i","--in": v,e:=need(); if e!=nil{return false,1,e}; cfg.In=&v; set("in")
        case "--input-dir": v,e:=need(); if e!=nil{return false,1,e}; cfg.InputDir=v; set("inputDir")
        case "--exclude": v,e:=need(); if e!=nil{return false,1,e}; cfg.Excludes=append(cfg.Excludes,v); set("excludes")
        case "--exclude-processing": v,e:=need(); if e!=nil{return false,1,e}; cfg.ExcludeProcessing=append(cfg.ExcludeProcessing,v); set("excludeProcessing")
        case "--include": v,e:=need(); if e!=nil{return false,1,e}; cfg.Includes=append(cfg.Includes,v); set("includes")
        case "-o","--out": v,e:=need(); if e!=nil{return false,1,e}; cfg.OutputFiles=append(cfg.OutputFiles,v); set("outputFiles")
        case "-t","--template": v,e:=need(); if e!=nil{return false,1,e}; cfg.Templates=append(cfg.Templates,v); set("templates")
        case "--output-dir": v,e:=need(); if e!=nil{return false,1,e}; cfg.OutputDir=v; set("outputDir")
        case "--output-map": v,e:=need(); if e!=nil{return false,1,e}; cfg.OutputMap=v; set("outputMap")
        case "--chmod": v,e:=need(); if e!=nil{return false,1,e}; cfg.Chmod=v; set("chmod")
        case "--left-delim": v,e:=need(); if e!=nil{return false,1,e}; cfg.LeftDelim=v; set("leftDelim")
        case "--right-delim": v,e:=need(); if e!=nil{return false,1,e}; cfg.RightDelim=v; set("rightDelim")
        case "--missing-key": v,e:=need(); if e!=nil{return false,1,e}; cfg.MissingKey=v; set("missingKey")
        case "--config": v,e:=need(); if e!=nil{return false,1,e}; cfg.ConfigPath=v; cfg.ConfigDisabled=(v==""); set("config")
        default: return false,1,fmt.Errorf("unknown flag: %s", name)
        }
    }
    return true,-1,nil
}

func logError(s string) {
    b,_ := json.Marshal(logEntry{Time:time.Now().UTC().Format(time.RFC3339Nano), Level:"ERROR", Msg:"", Err:s})
    fmt.Fprintln(os.Stderr,string(b))
}

func (a *App) loadDefs() {
    for _, d := range a.cfg.Datasources { alias,u := splitAlias(d); a.dsURLs[alias]=u }
    for _, h := range a.cfg.Headers {
        left, rest, ok := strings.Cut(h,"="); if !ok { continue }
        hn,hv,ok := strings.Cut(rest,":"); if !ok { continue }
        if a.dsHeaders[left]==nil { a.dsHeaders[left]=map[string][]string{} }
        a.dsHeaders[left][strings.TrimSpace(hn)] = append(a.dsHeaders[left][strings.TrimSpace(hn)], strings.TrimSpace(hv))
    }
    for _, p := range a.cfg.Plugins { n,path,ok:=strings.Cut(p,"="); if ok { a.plugins[n]=path } }
}

func (a *App) validate() error {
    opts:=[]string{}
    if a.cfg.In!=nil { opts=append(opts,"'in'") }
    if len(a.cfg.InputFiles)>0 { opts=append(opts,"'inputFiles'") }
    if a.cfg.InputDir!="" { opts=append(opts,"'inputDir'") }
    if len(opts)>1 { return fmt.Errorf("failed to validate config: only one of these options is supported at a time: %s\n---\n%s", strings.Join(opts, ", "), a.configSummary()) }
    if len(a.cfg.OutputFiles)>0 {
        n:=1; if len(a.cfg.InputFiles)>0 { n=len(a.cfg.InputFiles) }
        if len(a.cfg.OutputFiles)!=n { return fmt.Errorf("failed to validate config: must provide same number of 'outputFiles' (%d) as 'in' or 'inputFiles' (%d) options\n---\n%s", len(a.cfg.OutputFiles), n, a.configSummary()) }
    }
    return nil
}
func (a *App) configSummary() string {
    var b strings.Builder
    if a.cfg.In!=nil { fmt.Fprintf(&b,"in: %s\n", *a.cfg.In) }
    if len(a.cfg.InputFiles)>0 { fmt.Fprintf(&b,"inputFiles: [%s]\n", strings.Join(a.cfg.InputFiles, ", ")) }
    if a.cfg.InputDir!="" { fmt.Fprintf(&b,"inputDir: %s\n", a.cfg.InputDir) }
    if len(a.cfg.OutputFiles)>0 { fmt.Fprintf(&b,"outputFiles: [%s]\n", strings.Join(a.cfg.OutputFiles, ", ")) } else if a.cfg.InputDir=="" { b.WriteString("outputFiles: ['-']\n") }
    if a.cfg.InputDir!="" { fmt.Fprintf(&b,"outputDir: %s\n", a.cfg.OutputDir) }
    fmt.Fprintf(&b,"leftDelim: '%s'\nrightDelim: '%s'\nmissingKey: %s\npluginTimeout: 5s\n", a.cfg.LeftDelim, a.cfg.RightDelim, a.cfg.MissingKey)
    return b.String()
}

func (a *App) execute() error {
    if a.cfg.InputDir!="" { return a.executeDir() }
    ctx, err := a.context(); if err!=nil { return err }
    inputs := a.cfg.InputFiles
    if a.cfg.In!=nil { inputs=[]string{"<arg>"} }
    if len(inputs)==0 { inputs=[]string{"-"} }
    outputs := a.cfg.OutputFiles
    if len(outputs)==0 { outputs=[]string{"-"}; for len(outputs)<len(inputs) { outputs=append(outputs,"-") } }
    for i,infile := range inputs {
        var text []byte; name:=infile
        if a.cfg.In!=nil { text=[]byte(*a.cfg.In); name="<arg>" } else if infile=="-" { text=a.readStdin(); name="<stdin>" } else { var e error; text,e=os.ReadFile(infile); if e!=nil { return e } }
        out := outputs[i]
        var w io.Writer = os.Stdout
        var f *os.File
        if out!="-" { if err:=os.MkdirAll(filepath.Dir(out),0755); err!=nil && filepath.Dir(out)!="." { return err }; var e error; f,e=os.Create(out); if e!=nil{return e}; defer f.Close(); w=f }
        if err := a.render(name,string(text),ctx,w); err!=nil { return err }
        if f!=nil && a.cfg.Chmod!="" { if mode,err:=strconv.ParseUint(a.cfg.Chmod,8,32); err==nil { _=f.Chmod(os.FileMode(mode)) } }
    }
    return nil
}

func (a *App) executeDir() error {
    ctx,err:=a.context(); if err!=nil{return err}
    return filepath.WalkDir(a.cfg.InputDir, func(p string, de os.DirEntry, err error) error {
        if err!=nil{return err}; if de.IsDir(){return nil}
        rel,_:=filepath.Rel(a.cfg.InputDir,p); relSlash:=filepath.ToSlash(rel)
        if len(a.cfg.Includes)>0 && !matchesAny(relSlash,a.cfg.Includes){ return nil }
        if matchesAny(relSlash,a.cfg.Excludes){ return nil }
        outRel:=rel
        if a.cfg.OutputMap!="" { var buf bytes.Buffer; c:=copyMap(ctx); c["in"]=relSlash; if e:=a.render("<output-map>",a.cfg.OutputMap,c,&buf); e==nil { outRel=buf.String() } }
        outPath:=filepath.Join(a.cfg.OutputDir,outRel)
        if err:=os.MkdirAll(filepath.Dir(outPath),0755); err!=nil{return err}
        if matchesAny(relSlash,a.cfg.ExcludeProcessing){ data,e:=os.ReadFile(p); if e!=nil{return e}; return os.WriteFile(outPath,data,0644) }
        data,e:=os.ReadFile(p); if e!=nil{return e}
        f,e:=os.Create(outPath); if e!=nil{return e}; defer f.Close()
        c:=copyMap(ctx); c["in"]=relSlash
        return a.render(p,string(data),c,f)
    })
}

func matchesAny(rel string, pats []string) bool { for _,p:=range pats { if ok,_:=path.Match(p,rel); ok {return true}; if ok,_:=path.Match(p,path.Base(rel)); ok {return true}; if m,_:=filepath.Match(p, filepath.FromSlash(rel)); m{return true} }; return false }
func copyMap(m map[string]interface{}) map[string]interface{} { n:=map[string]interface{}{}; for k,v:=range m{n[k]=v}; return n }

func (a *App) context() (map[string]interface{}, error) {
    ctx:=map[string]interface{}{"Env": envMap()}
    for _, c := range a.cfg.Contexts {
        alias,u:=splitAlias(c)
        val,err:=a.loadURL(u); if err!=nil{return nil,err}
        if alias=="." { if mm,ok:=val.(map[string]interface{}); ok { ctx=mm } else { ctx=map[string]interface{}{".":val} } } else { ctx[alias]=val }
    }
    return ctx,nil
}

func envMap() map[string]string { m:=map[string]string{}; for _,e:=range os.Environ(){ k,v,_:=strings.Cut(e,"="); m[k]=v }; return m }

func splitAlias(s string) (string,string) {
    if a,u,ok:=strings.Cut(s,"="); ok { return a,u }
    base:=path.Base(strings.TrimRight(s,"/")); if strings.Contains(base,".") { base=strings.TrimSuffix(base,path.Ext(base)) }
    if base=="" { base=s }
    return base,s
}

func (a *App) render(name, text string, ctx interface{}, w io.Writer) error {
    root:=template.New("").Delims(a.cfg.LeftDelim,a.cfg.RightDelim).Option("missingkey="+missingOpt(a.cfg.MissingKey)).Funcs(a.funcMap())
    a.tmpl=root
    if err:=a.loadTemplates(root); err!=nil { return fmt.Errorf("renderTemplate: %w", err) }
    t:=root.New(name)
    if _,err:=t.Parse(text); err!=nil { return fmt.Errorf("renderTemplate: parse template %s: %w", name, err) }
    a.currentPath=name
    if err:=root.ExecuteTemplate(w,name,ctx); err!=nil { return fmt.Errorf("renderTemplate: failed to render template %s: %w", name, err) }
    return nil
}
func missingOpt(s string) string { if s=="error" {return "error"}; if s=="zero" {return "zero"}; return "default" }

func (a *App) loadTemplates(root *template.Template) error {
    for _, spec := range a.cfg.Templates {
        alias,u:=splitTemplateAlias(spec)
        p:=filePathFromURL(u)
        info,err:=os.Stat(p); if err!=nil{return err}
        if info.IsDir() {
            filepath.WalkDir(p, func(fp string, de os.DirEntry, err error) error {
                if err!=nil||de.IsDir(){return nil}
                rel,_:=filepath.Rel(p,fp); name:=path.Join(alias,filepath.ToSlash(rel)); data,e:=os.ReadFile(fp); if e==nil { root.New(name).Parse(string(data)) }
                return nil
            })
        } else { data,e:=os.ReadFile(p); if e!=nil{return e}; _,err=root.New(alias).Parse(string(data)); if err!=nil{return err} }
    }
    return nil
}
func splitTemplateAlias(s string)(string,string){ if a,u,ok:=strings.Cut(s,"="); ok{return a,u}; return s,s }
func filePathFromURL(s string) string { if strings.HasPrefix(s,"file://") { if u,err:=url.Parse(s); err==nil { return u.Path } }; return s }
func (a *App) readStdin() []byte { if !a.stdinOnce { a.stdinData,_=io.ReadAll(os.Stdin); a.stdinOnce=true }; return a.stdinData }

func (a *App) loadURL(u string) (interface{}, error) { raw,typ,err:=a.loadRaw(u); if err!=nil{return nil,err}; return parseData(raw,u,typ) }
func (a *App) loadRaw(u string) (string,string,error) {
    typ:=""; if parsed,err:=url.Parse(u); err==nil { typ=parsed.Query().Get("type") }
    if strings.HasPrefix(u,"stdin:") { return string(a.readStdin()),typ,nil }
    if strings.HasPrefix(u,"env:") { parsed,_:=url.Parse(u); name:=strings.TrimPrefix(parsed.Path,"/"); if name=="" { name=parsed.Host }; return os.Getenv(name),typ,nil }
    if strings.HasPrefix(u,"http://")||strings.HasPrefix(u,"https://") { req,_:=http.NewRequest("GET",u,nil); for _,hs:=range a.dsHeaders { for k,vs:=range hs { for _,v:=range vs { req.Header.Add(k,v) } } }; resp,err:=http.DefaultClient.Do(req); if err!=nil{return "","",err}; defer resp.Body.Close(); b,_:=io.ReadAll(resp.Body); if typ==""{typ=resp.Header.Get("Content-Type")}; return string(b),typ,nil }
    p:=filePathFromURL(u); b,err:=os.ReadFile(p); if err!=nil{return "","",err}; return string(b),typ,nil
}

func parseData(raw,u,typ string)(interface{},error){
    low:=strings.ToLower(typ); ext:=strings.ToLower(path.Ext(strings.Split(u,"?")[0]))
    if strings.Contains(low,"json")||ext==".json" { var v interface{}; dec:=json.NewDecoder(strings.NewReader(raw)); dec.UseNumber(); if err:=dec.Decode(&v); err!=nil{return nil,err}; return normalizeJSON(v),nil }
    if strings.Contains(low,"yaml")||strings.Contains(low,"x-yaml")||ext==".yaml"||ext==".yml" { return parseYAML(raw),nil }
    if strings.Contains(low,"toml")||ext==".toml" { return parseTOML(raw),nil }
    if strings.Contains(low,"csv")||ext==".csv" { r:=csv.NewReader(strings.NewReader(raw)); recs,err:=r.ReadAll(); return recs,err }
    return raw,nil
}
func normalizeJSON(v interface{}) interface{} { switch x:=v.(type){ case map[string]interface{}: for k,vv:= range x{x[k]=normalizeJSON(vv)}; return x; case []interface{}: for i,vv:=range x{x[i]=normalizeJSON(vv)}; return x; case json.Number: if i,err:=x.Int64(); err==nil {return i}; if f,err:=x.Float64(); err==nil{return f}; return x.String(); default:return v } }

// very small YAML/TOML readers, enough for gomplate examples and simple configs
func parseYAML(s string) interface{} { lines:=prepYAMLLines(s); v,_:=parseYAMLBlock(lines,0,0); return v }
type yline struct{ indent int; text string }
func prepYAMLLines(s string) []yline { out:=[]yline{}; for _,ln:=range strings.Split(strings.ReplaceAll(s,"\r\n","\n"),"\n"){ if strings.TrimSpace(ln)==""||strings.HasPrefix(strings.TrimSpace(ln),"#"){continue}; ind:=len(ln)-len(strings.TrimLeft(ln," ")); out=append(out,yline{ind,strings.TrimSpace(ln)}) }; return out }
func parseYAMLBlock(lines []yline, i, indent int)(interface{},int){ if i>=len(lines){return map[string]interface{}{},i}; if lines[i].indent<indent{return map[string]interface{}{},i}; if strings.HasPrefix(lines[i].text,"- "){ arr:=[]interface{}{}; for i<len(lines)&&lines[i].indent==indent&&strings.HasPrefix(lines[i].text,"- "){ rest:=strings.TrimSpace(lines[i].text[2:]); if rest=="" { v,ni:=parseYAMLBlock(lines,i+1,indent+2); arr=append(arr,v); i=ni } else if strings.Contains(rest,":")&&!strings.HasPrefix(rest,"\"") { k,v,_:=strings.Cut(rest,":"); m:=map[string]interface{}{strings.TrimSpace(k):parseScalar(strings.TrimSpace(v))}; arr=append(arr,m); i++ } else { arr=append(arr,parseScalar(rest)); i++ } }; return arr,i }
    m:=map[string]interface{}{}; for i<len(lines)&&lines[i].indent==indent&&!strings.HasPrefix(lines[i].text,"- "){ k,rest,ok:=strings.Cut(lines[i].text,":"); if !ok { i++; continue }; key:=strings.Trim(strings.TrimSpace(k),"'\""); rest=strings.TrimSpace(rest); if rest==""||rest=="|"||rest==">"||rest==">-" { if rest=="|"||rest==">"||rest==">-" { // literal: consume indented as text
                base:=indent+2; parts:=[]string{}; i++; for i<len(lines)&&lines[i].indent>=base { parts=append(parts, strings.Repeat(" ", max(0,lines[i].indent-base))+lines[i].text); i++ }; sep:="\n"; if strings.HasPrefix(rest,">"){sep=" "}; val:=strings.Join(parts,sep); if rest!="|-"&&rest!=">-"{val+="\n"}; m[key]=val
            } else { v,ni:=parseYAMLBlock(lines,i+1,indent+2); m[key]=v; i=ni } } else { m[key]=parseScalar(rest); i++ } }; return m,i }
func parseScalar(s string) interface{} { s=strings.TrimSpace(s); if s==""{return ""}; if (strings.HasPrefix(s,"'")&&strings.HasSuffix(s,"'"))||(strings.HasPrefix(s,"\"")&&strings.HasSuffix(s,"\"")){ u,err:=strconv.Unquote(s); if err==nil{return u}; return strings.Trim(s,"'\"") }; if strings.HasPrefix(s,"[")&&strings.HasSuffix(s,"]") { inner:=strings.TrimSpace(s[1:len(s)-1]); if inner==""{return []interface{}{}}; parts:=splitCSVLike(inner); arr:=[]interface{}{}; for _,p:=range parts{arr=append(arr,parseScalar(p))}; return arr }; if strings.HasPrefix(s,"{")&&strings.HasSuffix(s,"}") { var v interface{}; if json.Unmarshal([]byte(s),&v)==nil{return normalizeJSON(v)} }; switch strings.ToLower(s){case "true": return true; case "false": return false; case "null","~": return nil}; if i,err:=strconv.ParseInt(s,10,64); err==nil{return i}; if f,err:=strconv.ParseFloat(s,64); err==nil{return f}; return s }
func splitCSVLike(s string) []string { var out []string; var b strings.Builder; quote:=rune(0); for _,r:=range s{ if quote!=0 { b.WriteRune(r); if r==quote{quote=0}; continue}; if r=='\''||r=='"'{quote=r; b.WriteRune(r); continue}; if r==','{out=append(out,strings.TrimSpace(b.String())); b.Reset()} else {b.WriteRune(r)} }; out=append(out,strings.TrimSpace(b.String())); return out }
func parseTOML(s string) map[string]interface{} { m:=map[string]interface{}{}; for _,ln:=range strings.Split(s,"\n"){ ln=strings.TrimSpace(ln); if ln==""||strings.HasPrefix(ln,"#")||strings.HasPrefix(ln,"["){continue}; if k,v,ok:=strings.Cut(ln,"="); ok {m[strings.TrimSpace(k)]=parseScalar(strings.TrimSpace(v))} }; return m }

func applyConfigFile(cfg *Config, p string) error {
    b,err:=os.ReadFile(p); if err!=nil{return err}; raw:=parseYAML(string(b)); m,ok:=raw.(map[string]interface{}); if !ok{return nil}
    setStr:=func(key string, dst *string){ if cfg.cliSet[key]{return}; if v,ok:=m[key]; ok { *dst=fmt.Sprint(v) } }
    if !cfg.cliSet["in"] { if v,ok:=m["in"]; ok { s:=fmt.Sprint(v); cfg.In=&s } }
    if !cfg.cliSet["inputDir"] { setStr("inputDir", &cfg.InputDir) }
    if !cfg.cliSet["outputDir"] { setStr("outputDir", &cfg.OutputDir) }
    if !cfg.cliSet["outputMap"] { setStr("outputMap", &cfg.OutputMap) }
    if !cfg.cliSet["leftDelim"] { setStr("leftDelim", &cfg.LeftDelim) }
    if !cfg.cliSet["rightDelim"] { setStr("rightDelim", &cfg.RightDelim) }
    if !cfg.cliSet["missingKey"] { setStr("missingKey", &cfg.MissingKey) }
    if !cfg.cliSet["inputFiles"] { cfg.InputFiles = stringList(m["inputFiles"]) }
    if !cfg.cliSet["outputFiles"] { cfg.OutputFiles = stringList(m["outputFiles"]) }
    if !cfg.cliSet["templates"] { cfg.Templates = configSources(m["templates"]) }
    if !cfg.cliSet["datasources"] { cfg.Datasources = configSources(m["datasources"]) }
    if !cfg.cliSet["context"] { cfg.Contexts = configSources(m["context"]) }
    return nil
}
func stringList(v interface{}) []string { switch x:=v.(type){ case []interface{}: r:=[]string{}; for _,e:=range x{r=append(r,fmt.Sprint(e))}; return r; case []string: return x; case string: if x!=""{return []string{x}}}; return nil }
func configSources(v interface{}) []string { mm,ok:=v.(map[string]interface{}); if !ok{return stringList(v)}; keys:=make([]string,0,len(mm)); for k:=range mm{keys=append(keys,k)}; sort.Strings(keys); out:=[]string{}; for _,k:=range keys{ val:=mm[k]; if sub,ok:=val.(map[string]interface{}); ok { if u,ok:=sub["url"]; ok { out=append(out,k+"="+fmt.Sprint(u)) } } else { out=append(out,k+"="+fmt.Sprint(val)) } }; return out }

// Namespaces and functions
func (a *App) funcMap() template.FuncMap {
    fm:=template.FuncMap{}
    envns:=EnvNS{Env:envMap()}; mathns:=MathNS{}; strns:=StringsNS{}; coll:=CollNS{}; conv:=ConvNS{}; b64:=Base64NS{}; dat:=DataNS{a}; fil:=FileNS{}; rens:=RegexpNS{}; tim:=NewTimeNS(); netns:=NetNS{}; uuid:=UUIDNS{}; rnd:=RandomNS{}; test:=TestNS{}; tmplns:=TmplNS{a}
    fm["env"]=func() EnvNS{return EnvNS{Env:envMap()}}; fm["getenv"]=envns.Getenv
    fm["math"]=func() MathNS{return mathns}; fm["add"]=mathns.Add; fm["mul"]=mathns.Mul; fm["sub"]=mathns.Sub; fm["div"]=mathns.Div; fm["rem"]=mathns.Rem; fm["pow"]=mathns.Pow; fm["seq"]=mathns.Seq
    fm["strings"]=func() StringsNS{return strns}; fm["toUpper"]=strns.ToUpper; fm["toLower"]=strns.ToLower; fm["title"]=strns.Title; fm["replaceAll"]=strns.ReplaceAll; fm["trimSpace"]=strns.TrimSpace; fm["quote"]=strns.Quote; fm["squote"]=strns.Squote; fm["shellQuote"]=strns.ShellQuote; fm["indent"]=strns.Indent
    fm["coll"]=func() CollNS{return coll}; fm["dict"]=coll.Dict; fm["has"]=coll.Has; fm["keys"]=coll.Keys; fm["values"]=coll.Values; fm["append"]=coll.Append; fm["prepend"]=coll.Prepend; fm["uniq"]=coll.Uniq; fm["flatten"]=coll.Flatten; fm["reverse"]=coll.Reverse; fm["sort"]=coll.Sort; fm["merge"]=coll.Merge; fm["set"]=coll.Set; fm["unset"]=coll.Unset
    fm["conv"]=func() ConvNS{return conv}; fm["default"]=conv.Default; fm["join"]=conv.Join; fm["urlParse"]=conv.URL
    fm["base64"]=func() Base64NS{return b64}
    fm["data"]=func() DataNS{return dat}; fm["datasource"]=dat.Datasource; fm["ds"]=dat.Datasource; fm["include"]=dat.Include; fm["datasourceExists"]=dat.DatasourceExists; fm["datasourceReachable"]=dat.DatasourceReachable; fm["listDatasources"]=dat.ListDatasources; fm["defineDatasource"]=dat.DefineDatasource; fm["json"]=dat.JSON; fm["jsonArray"]=dat.JSONArray; fm["yaml"]=dat.YAML; fm["yamlArray"]=dat.YAMLArray; fm["toml"]=dat.TOML; fm["csv"]=dat.CSV; fm["csvByRow"]=dat.CSVByRow; fm["csvByColumn"]=dat.CSVByColumn; fm["toJSON"]=dat.ToJSON; fm["toJSONPretty"]=dat.ToJSONPretty; fm["toYAML"]=dat.ToYAML; fm["toTOML"]=dat.ToTOML; fm["toCSV"]=dat.ToCSV
    fm["file"]=func() FileNS{return fil}; fm["path"]=func() PathNS{return PathNS{false}}; fm["filepath"]=func() PathNS{return PathNS{true}}
    fm["regexp"]=func() RegexpNS{return rens}; fm["time"]=func() TimeNS{return tim}; fm["net"]=func() NetNS{return netns}; fm["uuid"]=func() UUIDNS{return uuid}; fm["random"]=func() RandomNS{return rnd}; fm["test"]=func() TestNS{return test}; fm["required"]=test.Required; fm["ternary"]=test.Ternary; fm["assert"]=test.Assert; fm["fail"]=test.Fail; fm["isKind"]=test.IsKind; fm["kind"]=test.Kind
    fm["tmpl"]=func() TmplNS{return tmplns}; fm["tpl"]=tmplns.Inline
    for name,cmd:=range a.plugins { n,c:=name,cmd; fm[n]=func(args ...interface{})(string,error){ ss:=[]string{}; for _,v:=range args{ss=append(ss,fmt.Sprint(v))}; out,err:=exec.Command(c,ss...).Output(); return string(out),err } }
    return fm
}

