type MathNS struct{}
func (MathNS) Add(v ...interface{}) interface{} { sum:=0.0; all:=true; for _,x:=range v{f,i:=num(x); sum+=f; all=all&&i}; if all{return int64(sum)}; return sum }
func (MathNS) Mul(v ...interface{}) interface{} { prod:=1.0; all:=true; for _,x:=range v{f,i:=num(x); prod*=f; all=all&&i}; if all{return int64(prod)}; return prod }
func (MathNS) Sub(a,b interface{}) interface{} { fa,ia:=num(a); fb,ib:=num(b); r:=fa-fb; if ia&&ib{return int64(r)}; return r }
func (MathNS) Div(a,b interface{}) float64 { fa,_:=num(a); fb,_:=num(b); return fa/fb }
func (MathNS) Rem(a,b interface{}) int64 { fa,_:=num(a); fb,_:=num(b); return int64(fa)%int64(fb) }
func (MathNS) Pow(a,b interface{}) float64 { fa,_:=num(a); fb,_:=num(b); return math.Pow(fa,fb) }
func (MathNS) Abs(a interface{}) interface{} { f,i:=num(a); if f<0{f=-f}; if i{return int64(f)}; return f }
func (MathNS) Ceil(a interface{}) float64 { f,_:=num(a); return math.Ceil(f) }
func (MathNS) Floor(a interface{}) float64 { f,_:=num(a); return math.Floor(f) }
func (MathNS) Round(a interface{}) float64 { f,_:=num(a); return math.Round(f) }
func (MathNS) Max(v ...interface{}) interface{} { maxv,_:=num(v[0]); all:=true; for _,x:=range v{f,i:=num(x); if f>maxv{maxv=f}; all=all&&i}; if all{return int64(maxv)}; return maxv }
func (MathNS) Min(v ...interface{}) interface{} { minv,_:=num(v[0]); all:=true; for _,x:=range v{f,i:=num(x); if f<minv{minv=f}; all=all&&i}; if all{return int64(minv)}; return minv }
func (MathNS) IsInt(v interface{}) bool { _,i:=num(v); return i }
func (MathNS) IsFloat(v interface{}) bool { switch v.(type){case float32,float64: return true}; return false }
func (MathNS) IsNum(v interface{}) bool { _,ok:=toFloat(v); return ok }
func (MathNS) Seq(args ...int64) []int64 { var start,end,step int64=1,0,1; if len(args)==1{end=args[0]} else if len(args)==2{start=args[0]; end=args[1]} else if len(args)>=3{start=args[0];end=args[1];step=args[2]}; if step==0{return []int64{}}; if end<start&&step>0{step=-step}; if end>start&&step<0{step=-step}; end -= (end-start)%step; seq:=[]int64{start}; for seq[len(seq)-1]!=end{seq=append(seq,seq[len(seq)-1]+step)}; return seq }
func num(v interface{})(float64,bool){ switch x:=v.(type){case int: return float64(x),true; case int64:return float64(x),true; case int32:return float64(x),true; case uint:return float64(x),true; case uint64:return float64(x),true; case float64:return x,false; case float32:return float64(x),false; case json.Number: if i,e:=x.Int64(); e==nil{return float64(i),true}; f,_:=x.Float64(); return f,false; case string: if i,e:=strconv.ParseInt(x,10,64); e==nil{return float64(i),true}; if f,e:=strconv.ParseFloat(x,64); e==nil{return f,false} }; rv:=reflect.ValueOf(v); if rv.IsValid(){ switch rv.Kind(){case reflect.Int,reflect.Int8,reflect.Int16,reflect.Int32,reflect.Int64: return float64(rv.Int()),true; case reflect.Uint,reflect.Uint8,reflect.Uint16,reflect.Uint32,reflect.Uint64: return float64(rv.Uint()),true; case reflect.Float32,reflect.Float64:return rv.Float(),false} }; return 0,true }
func toFloat(v interface{})(float64,bool){ f,_:=num(v); if fmt.Sprint(v)==""{return 0,false}; return f,true }

type StringsNS struct{}
func (StringsNS) ToUpper(s string) string { return strings.ToUpper(s) }
func (StringsNS) ToLower(s string) string { return strings.ToLower(s) }
func (StringsNS) Title(s string) string { return strings.Title(s) }
func (StringsNS) Contains(substr,s string) bool { return strings.Contains(s,substr) }
func (StringsNS) HasPrefix(prefix,s string) bool { return strings.HasPrefix(s,prefix) }
func (StringsNS) HasSuffix(suffix,s string) bool { return strings.HasSuffix(s,suffix) }
func (StringsNS) Split(sep,s string) []string { return strings.Split(s,sep) }
func (StringsNS) SplitN(sep string,n int,s string) []string { return strings.SplitN(s,sep,n) }
func (StringsNS) ReplaceAll(old,new,s string) string { return strings.ReplaceAll(s,old,new) }
func (StringsNS) Trim(cutset,s string) string { return strings.Trim(s,cutset) }
func (StringsNS) TrimLeft(cutset,s string) string { return strings.TrimLeft(s,cutset) }
func (StringsNS) TrimRight(cutset,s string) string { return strings.TrimRight(s,cutset) }
func (StringsNS) TrimPrefix(prefix,s string) string { return strings.TrimPrefix(s,prefix) }
func (StringsNS) TrimSuffix(suffix,s string) string { return strings.TrimSuffix(s,suffix) }
