func (StringsNS) Quote(s string) string { return strconv.Quote(s) }
func (StringsNS) Squote(s string) string { return "'"+strings.ReplaceAll(s,"'","'\\''")+"'" }
func (StringsNS) ShellQuote(s string) string { return (StringsNS{}).Squote(s) }
func (StringsNS) Indent(n int,s string) string { pref:=strings.Repeat(" ",n); lines:=strings.Split(s,"\n"); for i:=range lines{ if lines[i]!=""{lines[i]=pref+lines[i]} }; return strings.Join(lines,"\n") }
func (StringsNS) SkipLines(n int,s string) string { lines:=strings.Split(s,"\n"); if n>=len(lines){return ""}; return strings.Join(lines[n:],"\n") }
func (StringsNS) Abbrev(n int,s string) string { r:=[]rune(s); if len(r)<=n{return s}; if n<=3{return string(r[:n])}; return string(r[:n-3])+"..." }
func (StringsNS) Trunc(n int,s string) string { r:=[]rune(s); if n<0{ n=-n; if len(r)>n{return string(r[len(r)-n:])}; return s}; if len(r)>n{return string(r[:n])}; return s }
func (StringsNS) Slug(s string) string { s=strings.ToLower(s); re:=regexp.MustCompile(`[^a-z0-9]+`); return strings.Trim(re.ReplaceAllString(s,"-"),"-") }
func (StringsNS) CamelCase(s string) string { parts:=regexp.MustCompile(`[^A-Za-z0-9]+`).Split(s,-1); for i,p:=range parts{ if p!=""{parts[i]=strings.ToUpper(p[:1])+strings.ToLower(p[1:])} }; return strings.Join(parts,"") }
func (StringsNS) SnakeCase(s string) string { return strings.ReplaceAll((StringsNS{}).Slug(s),"-","_") }
func (StringsNS) KebabCase(s string) string { return (StringsNS{}).Slug(s) }
func (StringsNS) WordWrap(width int,s string) string { words:=strings.Fields(s); var out []string; line:=""; for _,w:=range words{ if len(line)+len(w)+1>width && line!=""{out=append(out,line); line=w}else{ if line!=""{line+=" "}; line+=w} }; if line!=""{out=append(out,line)}; return strings.Join(out,"\n") }
func (StringsNS) RuneCount(s string) int { return len([]rune(s)) }

type CollNS struct{}
func (CollNS) Dict(args ...interface{}) map[string]interface{} { m:=map[string]interface{}{}; for i:=0;i+1<len(args);i+=2{m[fmt.Sprint(args[i])]=args[i+1]}; return m }
func (CollNS) Slice(args ...interface{}) []interface{} { return args }
func (CollNS) GoSlice(s string,start,end int) string { if start<0{start=0}; if end>len(s){end=len(s)}; if start>end{return ""}; return s[start:end] }
func (CollNS) Has(coll interface{}, val interface{}) bool { rv:=reflect.ValueOf(coll); switch rv.Kind(){case reflect.Map: return rv.MapIndex(reflect.ValueOf(fmt.Sprint(val))).IsValid(); case reflect.Slice,reflect.Array: for i:=0;i<rv.Len();i++{ if reflect.DeepEqual(rv.Index(i).Interface(),val)||fmt.Sprint(rv.Index(i).Interface())==fmt.Sprint(val){return true} }; case reflect.String: return strings.Contains(rv.String(),fmt.Sprint(val))}; return false }
func (CollNS) Index(args ...interface{}) (interface{},error) { if len(args)<2{return nil,nil}; obj:=args[len(args)-1]; for _,k:=range args[:len(args)-1]{ v,err:=indexOne(obj,k); if err!=nil{return nil,err}; obj=v }; return obj,nil }
func indexOne(obj,k interface{})(interface{},error){ rv:=reflect.ValueOf(obj); if !rv.IsValid(){return nil,nil}; if rv.Kind()==reflect.Map{ mv:=rv.MapIndex(reflect.ValueOf(fmt.Sprint(k))); if mv.IsValid(){return mv.Interface()}; for _,mk:=range rv.MapKeys(){ if fmt.Sprint(mk.Interface())==fmt.Sprint(k){return rv.MapIndex(mk).Interface(),nil} }; return nil,nil }; if rv.Kind()==reflect.Slice||rv.Kind()==reflect.Array{ i,_:=strconv.Atoi(fmt.Sprint(k)); return rv.Index(i).Interface(),nil }; return nil,fmt.Errorf("can't index %T",obj) }
func (CollNS) Keys(m interface{}) []string { rv:=reflect.ValueOf(m); out:=[]string{}; if rv.Kind()==reflect.Map{ for _,k:=range rv.MapKeys(){out=append(out,fmt.Sprint(k.Interface()))}; sort.Strings(out)}; return out }
func (c CollNS) Values(m interface{}) []interface{} { ks:=c.Keys(m); out:=[]interface{}{}; for _,k:=range ks{v,_:=indexOne(m,k); out=append(out,v)}; return out }
func (CollNS) Append(v interface{}, list interface{}) []interface{} { return append(toIfaceSlice(list),v) }
func (CollNS) Prepend(v interface{}, list interface{}) []interface{} { return append([]interface{}{v},toIfaceSlice(list)...) }
func (CollNS) Uniq(list interface{}) []interface{} { seen:=map[string]bool{}; out:=[]interface{}{}; for _,v:=range toIfaceSlice(list){k:=fmt.Sprint(v); if !seen[k]{seen[k]=true; out=append(out,v)}}; return out }
func (CollNS) Flatten(list interface{}) []interface{} { out:=[]interface{}{}; var rec func(interface{}); rec=func(v interface{}){ rv:=reflect.ValueOf(v); if rv.IsValid()&&(rv.Kind()==reflect.Slice||rv.Kind()==reflect.Array){for i:=0;i<rv.Len();i++{rec(rv.Index(i).Interface())}}else{out=append(out,v)}}; rec(list); return out }
func (CollNS) Reverse(list interface{}) []interface{} { a:=toIfaceSlice(list); for i,j:=0,len(a)-1;i<j;i,j=i+1,j-1{a[i],a[j]=a[j],a[i]}; return a }
func (CollNS) Sort(list interface{}) []interface{} { a:=toIfaceSlice(list); sort.Slice(a,func(i,j int)bool{return fmt.Sprint(a[i])<fmt.Sprint(a[j])}); return a }
func (CollNS) Merge(ms ...interface{}) map[string]interface{} { out:=map[string]interface{}{}; for i:=len(ms)-1;i>=0;i--{ if m,ok:=toMap(ms[i]); ok {for k,v:=range m{out[k]=v}}}; return out }
func (CollNS) Pick(keys interface{}, m interface{}) map[string]interface{} { out:=map[string]interface{}{}; mm,_:=toMap(m); for _,k:=range toIfaceSlice(keys){ if v,ok:=mm[fmt.Sprint(k)]; ok{out[fmt.Sprint(k)]=v} }; return out }
func (CollNS) Omit(keys interface{}, m interface{}) map[string]interface{} { mm,_:=toMap(m); out:=map[string]interface{}{}; omit:=map[string]bool{}; for _,k:=range toIfaceSlice(keys){omit[fmt.Sprint(k)]=true}; for k,v:=range mm{if !omit[k]{out[k]=v}}; return out }
func (CollNS) Set(key string,val interface{}, m interface{}) map[string]interface{} { mm,_:=toMap(m); mm[key]=val; return mm }
func (CollNS) Unset(key string,m interface{}) map[string]interface{} { mm,_:=toMap(m); delete(mm,key); return mm }
func toIfaceSlice(v interface{}) []interface{} { if v==nil{return nil}; if s,ok:=v.([]interface{}); ok {return append([]interface{}{},s...)}; rv:=reflect.ValueOf(v); if rv.Kind()==reflect.Slice||rv.Kind()==reflect.Array{ out:=[]interface{}{}; for i:=0;i<rv.Len();i++{out=append(out,rv.Index(i).Interface())}; return out}; return []interface{}{v} }
func toMap(v interface{})(map[string]interface{},bool){ if m,ok:=v.(map[string]interface{}); ok{return m,true}; rv:=reflect.ValueOf(v); if rv.IsValid()&&rv.Kind()==reflect.Map{ out:=map[string]interface{}{}; for _,k:=range rv.MapKeys(){out[fmt.Sprint(k.Interface())]=rv.MapIndex(k).Interface()}; return out,true}; return map[string]interface{}{},false }

