type DataNS struct{ app *App }
func (d DataNS) Datasource(alias string, args ...string)(interface{},error){ if len(args)>0{alias=path.Join(alias,args[0])}; if v,ok:=d.app.dsCache[alias]; ok{return v,nil}; u,ok:=d.app.dsURLs[alias]; if !ok{return nil,fmt.Errorf("undefined datasource '%s': %%!w(<nil>)",alias)}; v,err:=d.app.loadURL(u); if err==nil{d.app.dsCache[alias]=v}; return v,err }
func (d DataNS) Include(alias string,args ...string)(string,error){ if len(args)>0{alias=path.Join(alias,args[0])}; if v,ok:=d.app.dsRaw[alias]; ok{return v,nil}; u,ok:=d.app.dsURLs[alias]; if !ok{return "",fmt.Errorf("undefined datasource '%s': %%!w(<nil>)",alias)}; raw,_,err:=d.app.loadRaw(u); if err==nil{d.app.dsRaw[alias]=raw}; return raw,err }
func (d DataNS) DatasourceExists(alias string) bool { _,ok:=d.app.dsURLs[alias]; return ok }
func (d DataNS) DatasourceReachable(alias string) bool { _,err:=d.Datasource(alias); return err==nil }
func (d DataNS) ListDatasources() []string { ks:=[]string{}; for k:=range d.app.dsURLs{ks=append(ks,k)}; sort.Strings(ks); return ks }
func (d DataNS) DefineDatasource(alias,u string) string { d.app.dsURLs[alias]=u; return "" }
func (DataNS) JSON(s string)(interface{},error){return parseData(s,"x.json","")}
func (DataNS) JSONArray(s string)(interface{},error){return parseData(s,"x.json","")}
func (DataNS) YAML(s string) interface{} { return parseYAML(s) }
