func (t TmplNS) Inline(args ...interface{})(string,error){ name:="inline"; idx:=0; if len(args)==0{return "",nil}; if len(args)>=3{ name=fmt.Sprint(args[0]); idx=1 }; text:=fmt.Sprint(args[idx]); var ctx interface{}=nil; if len(args)>idx+1{ctx=args[idx+1]}; _,e:=t.app.tmpl.New(name).Parse(text); if e!=nil{return "",e}; return t.Exec(name,ctx) }
